    m = 3
    # generate a random 3x3 grid with values 0-9
    grid = [[rng.randint(0, 9) for _ in range(m)] for _ in range(n)]
    # ensure at least one non-zero to avoid all-zero output
    if all(cell == 0 for row in grid for cell in row):
        grid[rng.randrange(n)][rng.randrange(m)] = rng.randint(1, 9)
