def solve(I):
    H = len(I)
    if H == 0:
        return []
    W = len(I[0])

    out = [[0] * W for _ in range(H)]

    # Collect the two positions for each colour.
    pos = {}
    for r in range(H):
        for c in range(W):
            v = I[r][c]
            if v != 0:
                pos.setdefault(v, []).append((r, c))

    # Draw vertical connecting lines first.
    for color, cells in pos.items():
        if len(cells) == 2:
            (r1, c1), (r2, c2) = cells
            if c1 == c2:
                for r in range(min(r1, r2), max(r1, r2) + 1):
                    out[r][c1] = color

    # Draw horizontal connecting lines, not overwriting vertical lines.
    for color, cells in pos.items():
        if len(cells) == 2:
            (r1, c1), (r2, c2) = cells
            if r1 == r2:
                r = r1
                for c in range(min(c1, c2), max(c1, c2) + 1):
                    if out[r][c] == 0:
                        out[r][c] = color

    return out


def gen_input(rng):
    while True:
        H = rng.randint(15, 28)
        W = rng.randint(10, 20)
        grid = [[0] * W for _ in range(H)]

        k = rng.randint(4, 6)
        colors = rng.sample(range(2, 10), k)

        # Make sure both orientations appear.
        orientations = ["H", "V"] + [rng.choice(["H", "V"]) for _ in range(k - 2)]
        rng.shuffle(orientations)

        h_rows = set()
        h_endpoint_cols = set()
        v_cols = set()

        ok = True

        # Place horizontal pairs first.
        for i, orient in enumerate(orientations):
            if orient != "H":
                continue
            color = colors[i]

            available_rows = [r for r in range(H) if r not in h_rows]
            if not available_rows:
                ok = False
                break
            r = rng.choice(available_rows)

            placed = False
            for _ in range(200):
                c1, c2 = rng.sample(range(W), 2)
                if grid[r][c1] == 0 and grid[r][c2] == 0:
                    grid[r][c1] = color
                    grid[r][c2] = color
                    h_rows.add(r)
                    h_endpoint_cols.add(c1)
                    h_endpoint_cols.add(c2)
                    placed = True
                    break

            if not placed:
                ok = False
                break

        if not ok:
            continue

        # Place vertical pairs after horizontal pairs, avoiding their endpoint columns.
        for i, orient in enumerate(orientations):
            if orient != "V":
                continue
            color = colors[i]

            available_cols = [
                c for c in range(W)
                if c not in v_cols and c not in h_endpoint_cols
            ]
            if not available_cols:
                ok = False
                break
            c = rng.choice(available_cols)

            available_rows = [r for r in range(H) if r not in h_rows]
            if len(available_rows) < 2:
                ok = False
                break

            placed = False
            for _ in range(200):
                r1, r2 = rng.sample(available_rows, 2)
                if grid[r1][c] == 0 and grid[r2][c] == 0:
                    grid[r1][c] = color
                    grid[r2][c] = color
                    v_cols.add(c)
                    placed = True
                    break

            if not placed:
                ok = False
                break

        if ok:
            return grid

def solve(I):
    O = [row[:] for row in I]
    n = len(I)
    m = len(I[0])
    # place patterns for 1s
    for r in range(n):
        for c in range(m):
            if I[r][c] == 1:
                for dr, dc in [(-1,0),(1,0),(0,-1),(0,1)]:
                    nr, nc = r+dr, c+dc
                    if 0 <= nr < n and 0 <= nc < m and O[nr][nc] == 0:
                        O[nr][nc] = 7
            elif I[r][c] == 2:
                for dr, dc in [(-1,-1),(-1,1),(1,-1),(1,1)]:
                    nr, nc = r+dr, c+dc
                    if 0 <= nr < n and 0 <= nc < m and O[nr][nc] == 0:
                        O[nr][nc] = 4
    return O

def gen_input(rng):
    n = 9
    grid = [[0]*n for _ in range(n)]
    # choose number of non-zero cells, between 3 and 5
    count = rng.randint(3, 5)
    # ensure at least one 1 and one 2
    values = [1, 2]
    # add extra random values from {1,2,6,8}
    for _ in range(count - 2):
        values.append(rng.choice([1,2,6,8]))
    rng.shuffle(values)
    # place them with some separation
    placed = []
    attempts = 0
    for v in values:
        while True:
            r = rng.randrange(n)
            c = rng.randrange(n)
            # avoid placing on top of existing or too close (Manhattan distance < 2)
            ok = True
            for (pr, pc) in placed:
                if abs(r-pr) + abs(c-pc) < 3:
                    ok = False
                    break
            if ok:
                grid[r][c] = v
                placed.append((r,c))
                break
            attempts += 1
            if attempts > 1000:
                # fallback: just place anywhere free
                while grid[r][c] != 0:
                    r = rng.randrange(n)
                    c = rng.randrange(n)
                grid[r][c] = v
                placed.append((r,c))
                break
    return grid

def solve(I):
    h = len(I)
    w = len(I[0])

    # connected components of non-zero cells
    comps = []
    seen = set()
    for r in range(h):
        for c in range(w):
            if I[r][c] == 0 or (r, c) in seen:
                continue
            stack = [(r, c)]
            seen.add((r, c))
            comp = []
            while stack:
                x, y = stack.pop()
                comp.append((x, y, I[x][y]))
                for dx, dy in ((1, 0), (-1, 0), (0, 1), (0, -1)):
                    nx, ny = x + dx, y + dy
                    if 0 <= nx < h and 0 <= ny < w and I[nx][ny] != 0 and (nx, ny) not in seen:
                        seen.add((nx, ny))
                        stack.append((nx, ny))
            comps.append(comp)

    # Most frequent non-zero colour is the "filler" colour.
    counts = {}
    for comp in comps:
        for _, _, v in comp:
            counts[v] = counts.get(v, 0) + 1
    filler = max(counts, key=counts.get)

    templates = []
    non_template_cells = []
    out = [[0] * w for _ in range(h)]

    for comp in comps:
        has_filler = any(v == filler for _, _, v in comp)
        if has_filler and len(comp) > 2:
            templates.append(comp)
        else:
            for cell in comp:
                non_template_cells.append(cell)
            # only isolated coloured pixels are carried over unchanged
            if len(comp) == 1:
                x, y, v = comp[0]
                out[x][y] = v

    non_template_dict = {(x, y): v for x, y, v in non_template_cells}

    def trans(r, c, k):
        if k == 0:
            return r, c
        if k == 1:
            return r, -c
        if k == 2:
            return -r, c
        if k == 3:
            return -r, -c
        if k == 4:
            return c, r
        if k == 5:
            return c, -r
        if k == 6:
            return -c, r
        if k == 7:
            return -c, -r
        return r, c

    for templ in templates:
        placed = None
        for k in range(8):
            t_cells = []
            anchor_cells = []
            for x, y, v in templ:
                tx, ty = trans(x, y, k)
                t_cells.append((tx, ty, v))
                if v != filler:
                    anchor_cells.append((tx, ty, v))

            for ai, (ax, ay, av) in enumerate(anchor_cells):
                for mx, my, mv in non_template_cells:
                    if mv != av:
                        continue
                    dx = mx - ax
                    dy = my - ay

                    ok = True
                    for ax2, ay2, av2 in anchor_cells:
                        pos = (ax2 + dx, ay2 + dy)
                        if non_template_dict.get(pos) != av2:
                            ok = False
                            break
                    if not ok:
                        continue

                    new_cells = []
                    for tx, ty, v in t_cells:
                        nx, ny = tx + dx, ty + dy
                        if not (0 <= nx < h and 0 <= ny < w):
                            ok = False
                            break
                        old = out[nx][ny]
                        if old != 0 and old != v:
                            ok = False
                            break
                        new_cells.append((nx, ny, v))
                    if not ok:
                        continue

                    placed = new_cells
                    break
                if placed is not None:
                    break
            if placed is not None:
                break

        if placed is not None:
            for x, y, v in placed:
                out[x][y] = v

    return out


def gen_input(rng):
    h = 16
    w = 16
    grid = [[0] * w for _ in range(h)]

    # A connected template object with filler 8 and anchor colours 1, 3, 4.
    pattern = [
        [1, 8, 4, 0],
        [8, 8, 8, 0],
        [0, 8, 3, 0],
    ]

    r0 = rng.randint(0, 2)
    c0 = rng.randint(0, 3)

    for i in range(len(pattern)):
        for j in range(len(pattern[0])):
            if pattern[i][j] != 0:
                grid[r0 + i][c0 + j] = pattern[i][j]

    anchors = [(0, 0, 1), (0, 2, 4), (2, 2, 3)]

    # Move the template's anchor points far away; only markers are placed there.
    dr = rng.randint(6, 9)
    dc = rng.randint(1, 5)

    for ar, ac, v in anchors:
        nr = r0 + ar + dr
        nc = c0 + ac + dc
        grid[nr][nc] = v

    return grid

def solve(I):
    H = len(I)
    W = len(I[0]) if H else 0

    # Small coloured key: every non-zero colour that is not the grey 8.
    key_rows = []
    key_cols = []
    for r in range(H):
        for c in range(W):
            v = I[r][c]
            if v != 0 and v != 8:
                key_rows.append(r)
                key_cols.append(c)

    gray_rows = []
    gray_cols = []
    for r in range(H):
        for c in range(W):
            if I[r][c] == 8:
                gray_rows.append(r)
                gray_cols.append(c)

    if not key_rows or not gray_rows:
        return [row[:] for row in I]

    kr0, kr1 = min(key_rows), max(key_rows)
    kc0, kc1 = min(key_cols), max(key_cols)
    key = [[I[r][c] for c in range(kc0, kc1 + 1)] for r in range(kr0, kr1 + 1)]

    gr0, gr1 = min(gray_rows), max(gray_rows)
    gc0, gc1 = min(gray_cols), max(gray_cols)

    kh = len(key)
    kw = len(key[0])

    # Rotate the key 90 degrees clockwise.
    rot = [[key[kh - 1 - j][i] for j in range(kh)] for i in range(kw)]
    rh = len(rot)
    rw = len(rot[0])

    gh = gr1 - gr0 + 1
    gw = gc1 - gc0 + 1

    sy = gh // rh
    sx = gw // rw
    if sy == 0 or sx == 0:
        return [row[:] for row in I]

    out = [row[:] for row in I]

    for i in range(rh):
        for j in range(rw):
            color = rot[i][j]
            for dr in range(sy):
                for dc in range(sx):
                    out[gr0 + i * sy + dr][gc0 + j * sx + dc] = color

    return out


def gen_input(rng):
    h = rng.randint(2, 4)
    w = rng.randint(2, 4)

    key = [[0] * w for _ in range(h)]
    for r in range(h):
        for c in range(w):
            if rng.random() < 0.5:
                key[r][c] = rng.randint(1, 4)

    # Ensure the key's bounding box is full: every row and column has a colour.
    for r in range(h):
        if not any(key[r]):
            key[r][rng.randrange(w)] = rng.randint(1, 4)
    for c in range(w):
        if not any(key[r][c] for r in range(h)):
            key[rng.randrange(h)][c] = rng.randint(1, 4)

    kh = len(key)
    kw = len(key[0])

    # Rotate the key 90 degrees clockwise to generate the large grey shape.
    rot = [[key[kh - 1 - j][i] for j in range(kh)] for i in range(kw)]

    scale = rng.randint(2, 3)
    ph = len(rot) * scale
    pw = len(rot[0]) * scale

    top_r = rng.randint(0, 1)
    top_c = rng.randint(0, 2)
    gap = rng.randint(4, 8)

    bot_r = top_r + kh + gap
    bot_c = rng.randint(0, 3)

    H = bot_r + ph + rng.randint(1, 3)
    W = max(top_c + kw, bot_c + pw) + rng.randint(1, 3)

    grid = [[0] * W for _ in range(H)]

    # Place the small coloured key.
    for r in range(kh):
        for c in range(kw):
            grid[top_r + r][top_c + c] = key[r][c]

    # Place the grey 8 shape corresponding to the nonzero rotated key cells.
    for i in range(len(rot)):
        for j in range(len(rot[0])):
            if rot[i][j] != 0:
                for dr in range(scale):
                    for dc in range(scale):
                        grid[bot_r + i * scale + dr][bot_c + j * scale + dc] = 8

    return grid

def solve(I):
    H = len(I)
    W = len(I[0])

    O = [[0] * (2 * W) for _ in range(2 * H)]

    # Place 2x2 copies of every non-zero input cell.
    for r in range(H):
        for c in range(W):
            v = I[r][c]
            if v != 0:
                O[r][c] = v
                O[r][c + W] = v
                O[r + H][c] = v
                O[r + H][c + W] = v

    # Collect the original coloured positions before adding filler 8s.
    colored = []
    for r in range(2 * H):
        for c in range(2 * W):
            if O[r][c] != 0:
                colored.append((r, c))

    # Fill diagonal neighbours of coloured cells with 8, unless already coloured.
    for r, c in colored:
        for dr, dc in ((-1, -1), (-1, 1), (1, -1), (1, 1)):
            nr, nc = r + dr, c + dc
            if 0 <= nr < 2 * H and 0 <= nc < 2 * W and O[nr][nc] == 0:
                O[nr][nc] = 8

    return O


