def solve(I):
    h = len(I)
    w = len(I[0])
    O = [row[:] for row in I]
    seen = [[False] * w for _ in range(h)]
    dirs = [(1, 0), (-1, 0), (0, 1), (0, -1)]

    for r in range(h):
        for c in range(w):
            if I[r][c] == 0 or seen[r][c]:
                continue
            color = I[r][c]
            stack = [(r, c)]
            seen[r][c] = True
            cells = []

            while stack:
                x, y = stack.pop()
                cells.append((x, y))
                for dx, dy in dirs:
                    nx, ny = x + dx, y + dy
                    if 0 <= nx < h and 0 <= ny < w:
                        if not seen[nx][ny] and I[nx][ny] == color:
                            seen[nx][ny] = True
                            stack.append((nx, ny))

            if len(cells) < 3:
                for x, y in cells:
                    O[x][y] = 3

    return O


