    colors = [1, 5, 7, 8]
    dirs = [(1, 0), (-1, 0), (0, 1), (0, -1)]

    def get_start():
        candidates = []
        for r in range(h):
            for c in range(w):
                if grid[r][c] != 0:
                    continue
                ok = True
                for dr, dc in dirs:
                    nr, nc = r + dr, c + dc
                    if 0 <= nr < h and 0 <= nc < w and grid[nr][nc] != 0:
                        ok = False
                        break
                if ok:
                    candidates.append((r, c))
        return rng.choice(candidates) if candidates else None

    def place_cluster(size, color):
        start = get_start()
        if start is None:
            return
        cells = [start]
        grid[start[0]][start[1]] = color

        for _ in range(size - 1):
            candidates = []
            for x, y in cells:
                for dx, dy in dirs:
                    nx, ny = x + dx, y + dy
                    if 0 <= nx < h and 0 <= ny < w and grid[nx][ny] == 0:
                        if (nx, ny) in cells:
                            continue
                        ok = True
                        for dx2, dy2 in dirs:
                            nnx, nny = nx + dx2, ny + dy2
                            if 0 <= nnx < h and 0 <= nny < w:
                                if grid[nnx][nny] != 0 and (nnx, nny) not in cells:
                                    ok = False
                                    break
                        if ok:
                            candidates.append((nx, ny))
            if not candidates:
                break
            chosen = rng.choice(candidates)
            grid[chosen[0]][chosen[1]] = color
            cells.append(chosen)

    sizes = [1, 2, rng.randint(3, 5), rng.randint(1, 2), rng.randint(3, 5)]
    for s in sizes:
        place_cluster(s, rng.choice(colors))

    extras = rng.randint(0, 3)
