        place_cluster(rng.randint(1, 4), rng.choice(colors))

    return grid

def solve(I):
    H = len(I)
    W = len(I[0])
    O = [row[:] for row in I]

    left = all(I[r][0] == 5 for r in range(H))
    right = all(I[r][W - 1] == 5 for r in range(H))
    top = all(I[0][c] == 5 for c in range(W))
    bottom = all(I[H - 1][c] == 5 for c in range(W))

    if left or right:
        for r in range(H):
            seeds = []
            for c in range(W):
                v = I[r][c]
                if v not in (0, 5):
                    seeds.append((c, v))
            if not seeds:
                continue
            seeds.sort()

            if right:
                for i, (c, color) in enumerate(seeds):
                    next_c = seeds[i + 1][0] if i + 1 < len(seeds) else W - 1
                    O[r][c:next_c] = [color] * (next_c - c)
            else:  # left border
                prev_c = None
                for c, color in seeds:
                    start = prev_c + 1 if prev_c is not None else 1
                    O[r][start:c + 1] = [color] * (c - start + 1)
                    prev_c = c

    elif top or bottom:
        for c in range(W):
            seeds = []
            for r in range(H):
                v = I[r][c]
                if v not in (0, 5):
                    seeds.append((r, v))
            if not seeds:
                continue
            seeds.sort()

            if bottom:
                for i, (r, color) in enumerate(seeds):
                    next_r = seeds[i + 1][0] if i + 1 < len(seeds) else H - 1
                    for rr in range(r, next_r):
                        O[rr][c] = color
            else:  # top border
                prev_r = None
                for r, color in seeds:
                    start = prev_r + 1 if prev_r is not None else 1
                    for rr in range(start, r + 1):
                        O[rr][c] = color
                    prev_r = r

    return O


