def solve(I):
    from collections import deque

    H = len(I)
    W = len(I[0])
    out = [row[:] for row in I]
    visited = [[False] * W for _ in range(H)]

    for r in range(H):
        for c in range(W):
            if I[r][c] != 7 and not visited[r][c]:
                color = I[r][c]
                q = deque([(r, c)])
                visited[r][c] = True
                cells = []

                while q:
                    cr, cc = q.popleft()
                    cells.append((cr, cc))
                    for dr, dc in ((1, 0), (-1, 0), (0, 1), (0, -1)):
                        nr, nc = cr + dr, cc + dc
                        if 0 <= nr < H and 0 <= nc < W:
                            if not visited[nr][nc] and I[nr][nc] == color:
                                visited[nr][nc] = True
                                q.append((nr, nc))

                rs = [p[0] for p in cells]
                cs = [p[1] for p in cells]
                minr, maxr = min(rs), max(rs)
                minc, maxc = min(cs), max(cs)

                h = maxr - minr + 1
                w = maxc - minc + 1

                if h == w and h >= 2:
                    cell_set = set(cells)
                    corners = [(minr, minc), (minr, maxc), (maxr, minc), (maxr, maxc)]
                    if all(p in cell_set for p in corners):
                        add_pts = [
                            (minr - 1, minc), (minr, minc - 1),
                            (minr - 1, maxc), (minr, maxc + 1),
                            (maxr + 1, minc), (maxr, minc - 1),
                            (maxr + 1, maxc), (maxr, maxc + 1),
                        ]
                        for rr, cc in add_pts:
                            if 0 <= rr < H and 0 <= cc < W and out[rr][cc] == 7:
                                out[rr][cc] = 2

    return out


