def solve(I):
    rows = I
    sep_rows = [r for r, row in enumerate(rows) if all(v == 8 for v in row)]

    bands = []
    for a, b in zip(sep_rows, sep_rows[1:]):
        if b > a + 1:
            bands.append(rows[a + 1:b])

    band_labels = [band[0][0] for band in bands]
    n_bands = len(bands)

    parsed_bands = []
    for band in bands:
        first = band[0]
        seps = [i for i, v in enumerate(first) if v == 8]
        cells = []
        start = 1
        for s in seps:
            if s > start:
                cells.append([row[start:s] for row in band])
            start = s + 1
        parsed_bands.append(cells)

    n_cells = len(parsed_bands[0])
    out_cells = []

    for j in range(n_cells):
        stack = [parsed_bands[b][j] for b in range(n_bands)]

        mask = None
        source = None
        source_color = None
        source_label = None

        for idx, cell in enumerate(stack):
            vals = set()
            for row in cell:
                vals.update(row)
            non1 = vals - {1}

            # source: a solid block of one colour, not 2/8
            if len(non1) == 1 and 2 not in non1 and 8 not in non1:
                if source is None:
                    source = cell
                    source_color = next(iter(non1))
                    source_label = band_labels[idx]

            # mask: contains both 2 and 8
            if 2 in non1 and 8 in non1:
                if mask is None:
                    mask = cell

        h = len(mask)
        w = len(mask[0])
        out_cell = []
        for r in range(h):
            out_row = []
            for c in range(w):
                v = mask[r][c]
                if v == 2:
                    out_row.append(source_color)
                elif v == 8:
                    out_row.append(8)
                else:
                    out_row.append(source_label)
            out_cell.append(out_row)
        out_cells.append(out_cell)

    height = len(out_cells[0])
    result = []
    for r in range(height):
        row = []
        for j, cell in enumerate(out_cells):
            row.extend(cell[r])
            if j != n_cells - 1:
                row.append(8)
        result.append(row)

    return result


