                        if 0 <= nr < H and 0 <= nc < W and not visited[nr][nc] and I[nr][nc] == color:
                            visited[nr][nc] = True
                            stack.append((nr,nc))
                # compute bounding box
                minr = min(x for x,y in cells)
                maxr = max(x for x,y in cells)
                minc = min(y for x,y in cells)
                maxc = max(y for x,y in cells)
                # check if it's a filled rectangle: all cells in bbox have same color and are in component
                is_rect = True
                for rr in range(minr, maxr+1):
