    from collections import deque
    for r in range(H):
        for c in range(W):
            if I[r][c] == 8 and not visited[r][c]:
                # BFS
                q = deque()
                q.append((r,c))
                visited[r][c] = True
                cells = []
                while q:
                    cr, cc = q.popleft()
                    cells.append((cr,cc))
                    for dr, dc in [(1,0),(-1,0),(0,1),(0,-1)]:
                        nr, nc = cr+dr, cc+dc
                        if 0 <= nr < H and 0 <= nc < W and not visited[nr][nc] and I[nr][nc] == 8:
                            visited[nr][nc] = True
                            q.append((nr,nc))
                comps.append((len(cells), cells))

    if not comps:
        return [row[:] for row in I]

    # find smallest
    min_size = min(s for s,_ in comps)
    smallest_cells = set()
    for s, cells in comps:
        if s == min_size:
            smallest_cells = set(cells)
            break

    out = [[0]*W for _ in range(H)]
    for r in range(H):
