    visited = [[False]*W for _ in range(H)]
    for r in range(H):
        for c in range(W):
            if I[r][c] == 5 and not visited[r][c]:
                # BFS to find component
                stack = [(r, c)]
                visited[r][c] = True
                cells = []
                while stack:
                    cr, cc = stack.pop()
                    cells.append((cr, cc))
                    for dr, dc in [(-1,0),(1,0),(0,-1),(0,1)]:
                        nr, nc = cr+dr, cc+dc
                        if 0 <= nr < H and 0 <= nc < W and not visited[nr][nc] and I[nr][nc] == 5:
                            visited[nr][nc] = True
                            stack.append((nr, nc))
                # Compute bounding box
                min_r = min(x for x, y in cells)
                max_r = max(x for x, y in cells)
                min_c = min(y for x, y in cells)
                max_c = max(y for x, y in cells)
                # Fill pattern
                for rr in range(min_r, max_r+1):
                    for cc in range(min_c, max_c+1):
                        if (rr == min_r or rr == max_r) and (cc == min_c or cc == max_c):
