def solve(I):
    # Find distinct colors
    colors = set()
    for row in I:
        for v in row:
            if v != 0:
                colors.add(v)
    colors = list(colors)
    if not colors:
        return []

    # Compute bounding boxes
    bbox = {}
    for c in colors:
        minr = minc = 10**9
        maxr = maxc = -1
        for r, row in enumerate(I):
            for cc, v in enumerate(row):
                if v == c:
                    minr = min(minr, r)
                    maxr = max(maxr, r)
                    minc = min(minc, cc)
                    maxc = max(maxc, cc)
        bbox[c] = (minr, maxr, minc, maxc)

    # Sort by area descending
    sorted_colors = sorted(colors, key=lambda c: (bbox[c][1]-bbox[c][0]+1)*(bbox[c][3]-bbox[c][2]+1), reverse=True)
    n = len(sorted_colors)

    inner_h = bbox[sorted_colors[-1]][1] - bbox[sorted_colors[-1]][0] + 1
    inner_w = bbox[sorted_colors[-1]][3] - bbox[sorted_colors[-1]][2] + 1

    H = inner_h + 2*(n-1)
    W = inner_w + 2*(n-1)

    out = [[0]*W for _ in range(H)]

    for i, c in enumerate(sorted_colors):
        offset = i
        if i == n-1:
            # fill inner rectangle
            for r in range(offset, H-offset):
                for cc in range(offset, W-offset):
                    out[r][cc] = c
        else:
            # draw border
            for r in range(offset, H-offset):
                out[r][offset] = c
                out[r][W-1-offset] = c
            for cc in range(offset, W-offset):
                out[offset][cc] = c
                out[H-1-offset][cc] = c

    return out

